import re
import subprocess
from pathlib import Path
from langchain_core.tools import tool

@tool
def trigger_log_rotation(config_name: str, dry_run: bool=True) -> str:
    if not re.fullmatch('[A-Za-z0-9_.-]+', config_name):
        return 'error: invalid config name'
    cfg = Path('/etc/logrotate.d') / config_name
    if not cfg.is_file():
        return 'error: config not found'
    cmd = ['logrotate', '-f', str(cfg)]
    if dry_run:
        cmd = ['logrotate', '-d', str(cfg)]
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
    # Read the logrotate state file to report last rotation info
    state_info = ''
    state_file = Path('/var/lib/logrotate/status')
    try:
        if state_file.is_file():
            lines = state_file.read_text(errors='replace').splitlines()
            matches = [l for l in lines if config_name in l]
            state_info = '\nstate:\n' + '\n'.join(matches[:10])
    except OSError:
        state_info = ''
    return f'exit={proc.returncode}\n{proc.stdout}{proc.stderr}{state_info}'
